        assertEquals(expected, new HashSet<List<Integer>>(result));
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldFindCombinationsThatSumToEight() {

        Solution solution = new Solution();

        List<List<Integer>> result = solution.combinationSum(
            new int[]{2, 3, 5},
            8
        );

        Set<List<Integer>> expected = new HashSet<List<Integer>>(Arrays.asList(
            Arrays.asList(2, 2, 2, 2),
            Arrays.asList(2, 3, 3),
            Arrays.asList(3, 5)
        ));

        assertEquals(expected, new HashSet<List<Integer>>(result));
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldReturnEmptyWhenTargetUnreachable() {

        Solution solution = new Solution();

        assertTrue(
